def is_balanced(text):
    bracket_pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in text:
        if char in bracket_pairs.values():
            stack.append(char)
        elif char in bracket_pairs:
            if not stack or stack[-1] != bracket_pairs[char]:
                return False
            stack.pop()
    return not stack
```

