def is_balanced(text):
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}

    for char in text:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        elif char in mapping.values():
            stack.append(char)

    return not stack
